package com.contenthub.api;
import com.contenthub.domain.Content;import com.contenthub.repository.ContentRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class ContentController{private final ContentRepository repo;public ContentController(ContentRepository r){repo=r;}record Request(@NotBlank String title,@NotBlank @Pattern(regexp="[a-z0-9-]+")String slug,String excerpt,@NotBlank String body,String category,String status){}@GetMapping("/contents")public List<Content> all(){return repo.findAllByOrderByCreatedAtDesc();}@GetMapping("/public/contents")public List<Content> published(){return repo.findByStatusOrderByCreatedAtDesc("PUBLISHED");}@PostMapping("/contents")public Content create(@Valid @RequestBody Request r){if(repo.existsBySlug(r.slug()))throw new IllegalArgumentException("Slug zaten kullanımda");return repo.save(new Content(r.title(),r.slug(),r.excerpt(),r.body(),r.category(),r.status()==null?"DRAFT":r.status()));}@PutMapping("/contents/{id}")public Content update(@PathVariable Long id,@Valid @RequestBody Request r){var c=repo.findById(id).orElseThrow(()->new IllegalArgumentException("İçerik bulunamadı"));c.update(r.title(),r.slug(),r.excerpt(),r.body(),r.category(),r.status()==null?"DRAFT":r.status());return repo.save(c);}@DeleteMapping("/contents/{id}")public Map<String,String> delete(@PathVariable Long id){repo.deleteById(id);return Map.of("message","Silindi");}@GetMapping("/dashboard")public Map<String,Long> dashboard(){return Map.of("totalContents",repo.count(),"publishedContents",repo.countByStatus("PUBLISHED"));}}